import React,{useEffect,useMemo,useState} from 'react';
import {BrowserRouter,Routes,Route,Navigate,Link,NavLink,useLocation,useNavigate,useParams,useSearchParams} from 'react-router-dom';
import {Building2,Home,Search,CalendarCheck,UserRound,LayoutDashboard,Boxes,CalendarClock,ClipboardList,ShieldCheck,Users,Store,Plus,ArrowRight,ArrowUpRight,ChevronRight,MapPin,UsersRound,Clock3,Wallet,PartyPopper,School,DoorOpen,Presentation,Trees,SlidersHorizontal,Sparkles,CalendarDays,CheckCircle2,XCircle,QrCode,Eye,EyeOff,LogOut,RefreshCcw,Pencil,Trash2,Power,Mail,User,Info,Menu,Check,Download} from 'lucide-react';
import {QRCodeSVG} from 'qrcode.react';
import {AppProvider,useApp} from './context/AppContext.jsx';
import {Button,Field,Badge,Spinner,EmptyState,Modal,Confirm,Toast,Header,Stat,Table,Chips} from './components/ui.jsx';
import SpaceCard from './components/SpaceCard.jsx';
import BookingCard,{formatDate} from './components/BookingCard.jsx';
import SpaceForm from './components/SpaceForm.jsx';
